<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\Aircraft; use Illuminate\Http\Request; use Illuminate\Database\QueryException;
class AircraftController extends Controller { public function index(){return Aircraft::withCount('flights')->latest()->paginate(15);} public function store(Request $r){$d=$r->validate(['model'=>'required|string|max:100','registration'=>'required|string|max:30|unique:aircraft','capacity'=>'required|integer|min:1','manufacturer'=>'required|string|max:100']);return response()->json(Aircraft::create($d),201);} public function show(Aircraft $aircraft){return $aircraft->load('flights');} public function update(Request $r,Aircraft $aircraft){$d=$r->validate(['model'=>'sometimes|required|string|max:100','registration'=>'sometimes|required|string|max:30|unique:aircraft,registration,'.$aircraft->id,'capacity'=>'sometimes|required|integer|min:1','manufacturer'=>'sometimes|required|string|max:100']);$aircraft->update($d);return $aircraft->fresh();} public function destroy(Aircraft $aircraft){if($aircraft->flights()->exists())return response()->json(['message'=>'این هواپیما در پرواز ثبت‌شده استفاده شده است.'],409);$aircraft->delete();return response()->json(['message'=>'هواپیما حذف شد']);} }
